insert into public.communication_templates (key, language, subject, body, active)
values
('BOOKING_RECEIVED','en','Booking received', E'Hello {{customer_name}},\n\nThank you for booking with *ALHARAMAIN ELITE*. We are pleased to confirm that we have received your booking *{{booking_id}}*.\n\n*Package:* {{package_name}}\n*Guests:* {{guest_count}}\n*Travel period:* {{travel_period}}\n\nOur team will now review the booking and guide you through the next step.\n\n*A Journey Worth Remembering.*', true),
('BOOKING_RECEIVED','so','Booking-ga waa la helay', E'Salaan {{customer_name}},\n\nWaad ku mahadsan tahay inaad ka dooratay *ALHARAMAIN ELITE*. Waxaan ku faraxsanahay inaan xaqiijinno inaan helnay booking-gaaga *{{booking_id}}*.\n\n*Xirmada:* {{package_name}}\n*Martida:* {{guest_count}}\n*Muddada safarka:* {{travel_period}}\n\nKooxdayadu hadda waxay dib u eegi doontaa booking-ga waxayna kula socodsiin doontaa tallaabada xigta.\n\n*A Journey Worth Remembering.*', true),
('BOOKING_RECEIVED','ar','تم استلام الحجز', E'مرحبًا {{customer_name}}،\n\nشكرًا لاختياركم *ALHARAMAIN ELITE*. يسعدنا تأكيد استلام حجزكم رقم *{{booking_id}}*.\n\n*الباقة:* {{package_name}}\n*عدد الضيوف:* {{guest_count}}\n*فترة السفر:* {{travel_period}}\n\nسيقوم فريقنا الآن بمراجعة الحجز ومتابعة الخطوة التالية معكم.\n\n*A Journey Worth Remembering.*', true)
